/** Path segments relative to the site root (handles Windows file:// and BASE_PATH). */
function ymiatSiteParts() {
  const path = window.location.pathname.replace(/\\/g, '/');
  let parts = path.replace(/^\//, '').split('/').filter(Boolean);
  // Drop Windows drive letter ("d:")
  if (parts[0] && /^[a-zA-Z]:$/.test(parts[0])) {
    parts = parts.slice(1);
  }
  // Prefer content after repo folder name when opening via file://
  const rootMarkers = ['dndlite', 'easytabletopfantasy'];
  for (let i = 0; i < parts.length; i++) {
    if (rootMarkers.indexOf(parts[i].toLowerCase()) >= 0) {
      parts = parts.slice(i + 1);
      break;
    }
  }
  // Strip deploy BASE_PATH segments
  const base = BASE_PATH.replace(/^\//, '').replace(/\/$/, '');
  if (base) {
    const baseParts = base.split('/').filter(Boolean);
    if (
      baseParts.length &&
      parts.slice(0, baseParts.length).join('/') === baseParts.join('/')
    ) {
      parts = parts.slice(baseParts.length);
    }
  }
  return parts;
}

function ymiatDetectLocale() {
  const parts = ymiatSiteParts();
  return parts[0] === 'nl' ? 'nl' : 'en';
}

function ymiatPathDepth() {
  const parts = ymiatSiteParts();
  if (!parts.length) return 0;
  const last = parts[parts.length - 1];
  const hasFile = last.includes('.');
  return hasFile ? parts.length - 1 : parts.length;
}

function ymiatRelativePrefix(depth) {
  if (depth <= 0) return '';
  return '../'.repeat(depth);
}

function ymiatIsLocalHost() {
  const protocol = window.location.protocol;
  const hostname = window.location.hostname;
  return protocol === 'file:' || hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '';
}

/** Locale content root (EN site root or .../nl/). */
function getRootPath() {
  const locale = ymiatDetectLocale();
  const depth = ymiatPathDepth();
  if (ymiatIsLocalHost()) {
    let contentDepth = depth;
    if (locale === 'nl') {
      contentDepth = Math.max(0, depth - 1);
    }
    return ymiatRelativePrefix(contentDepth);
  }
  const base = BASE_PATH ? (BASE_PATH.endsWith('/') ? BASE_PATH : BASE_PATH + '/') : '/';
  return locale === 'nl' ? base + 'nl/' : base;
}

/** Shared assets root (never under /nl/). */
function getAssetsPath() {
  const depth = ymiatPathDepth();
  if (ymiatIsLocalHost()) {
    return ymiatRelativePrefix(depth);
  }
  if (BASE_PATH) {
    return BASE_PATH.endsWith('/') ? BASE_PATH : BASE_PATH + '/';
  }
  return ymiatRelativePrefix(depth);
}

function ymiatChrome(locale) {
  const pack = (window.YMIAT_I18N_CHROME && window.YMIAT_I18N_CHROME[locale])
    || (window.YMIAT_I18N_CHROME && window.YMIAT_I18N_CHROME.en)
    || null;
  return pack;
}

function ymiatEscapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

